#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <sched.h>

// Helper function for error checking
void check_error(int ret, const char *func) {
    if (ret != 0) {
        fprintf(stderr, "%s failed: %s (Error code %d)\n", func, strerror(ret), ret);
        // Exit failure unless error is specific permission/unsupported warning
        if (ret != EPERM && ret != EINVAL) {
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
    pthread_attr_t attr;
    int policy_set = SCHED_RR;
    int policy_retrieved;
    int ret;

    // 1. Initialize attributes object
    ret = pthread_attr_init(&attr);
    check_error(ret, "pthread_attr_init");

    // 2. Set the desired scheduling policy (e.g., Round-Robin)
    printf("Attempting to set policy to SCHED_RR...\n");
    ret = pthread_attr_setschedpolicy(&attr, policy_set);

    // SCHED_RR often requires root privileges (EPERM)
    if (ret != 0) {
        fprintf(stderr, "Warning: Setschedpolicy failed. Policy may require root or be unsupported. Code: %d (%s)\n", ret, strerror(ret));
    } else {
        printf("Policy set successfully in attribute object.\n");
    }

    // 3. Must set inheritance to explicit for the policy to take effect on thread creation
    ret = pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
    check_error(ret, "pthread_attr_setinheritsched");

    // 4. Retrieve and verify the set policy
    ret = pthread_attr_getschedpolicy(&attr, &policy_retrieved);
    check_error(ret, "pthread_attr_getschedpolicy");

    // 5. Print retrieved status
    printf("\n--- Verification ---\n");
    printf("Policy retrieved: %d\n", policy_retrieved);
    if (policy_retrieved == SCHED_RR) {
        printf("Verification successful: Policy is SCHED_RR.\n");
    } else {
        printf("Verification failed: Policy is not SCHED_RR (System likely defaulted to %d).\n", policy_retrieved);
    }

    // 6. Cleanup
    pthread_attr_destroy(&attr);

    return 0;
}
